CREATE TABLE "food_log" (
	"household_id" text NOT NULL,
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "food_log_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"uid" text NOT NULL,
	"person_id" integer NOT NULL,
	"date" date NOT NULL,
	"slot" text NOT NULL,
	"kind" text NOT NULL,
	"recipe_slug" text,
	"servings" double precision,
	"ingredient_slug" text,
	"household_food_id" integer,
	"grams" double precision,
	"display_qty" double precision,
	"display_unit" text,
	"plan_id" integer,
	"planned_recipe_slug" text,
	"planned_servings" double precision,
	"note" text,
	"created_at" timestamp with time zone NOT NULL,
	"updated_at" timestamp with time zone NOT NULL,
	"created_by_person_id" integer,
	CONSTRAINT "food_log_slot_ck" CHECK ("food_log"."slot" in ('breakfast', 'lunch', 'dinner', 'snack', 'shake')),
	CONSTRAINT "food_log_kind_ck" CHECK ("food_log"."kind" in ('planned', 'skipped', 'swap', 'extra')),
	CONSTRAINT "food_log_item_ck" CHECK ((
    ("food_log"."recipe_slug" is not null and "food_log"."servings" is not null and "food_log"."servings" > 0 and "food_log"."ingredient_slug" is null and "food_log"."household_food_id" is null and "food_log"."grams" is null)
    or ("food_log"."ingredient_slug" is not null and "food_log"."grams" is not null and "food_log"."grams" > 0 and "food_log"."recipe_slug" is null and "food_log"."household_food_id" is null and "food_log"."servings" is null)
    or ("food_log"."household_food_id" is not null and "food_log"."grams" is not null and "food_log"."grams" > 0 and "food_log"."recipe_slug" is null and "food_log"."ingredient_slug" is null and "food_log"."servings" is null)
  )),
	CONSTRAINT "food_log_planned_ck" CHECK ("food_log"."planned_servings" is null or "food_log"."planned_servings" > 0)
);
