CREATE TABLE "household_foods" (
	"household_id" text NOT NULL,
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "household_foods_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"uid" text NOT NULL,
	"created_at" timestamp with time zone NOT NULL,
	"updated_at" timestamp with time zone NOT NULL,
	"created_by_person_id" integer,
	"name" text NOT NULL,
	"brand" text,
	"barcode" text,
	"state" text DEFAULT 'ready' NOT NULL,
	"aisle" text DEFAULT 'packaged' NOT NULL,
	"kcal" double precision NOT NULL,
	"protein_g" double precision NOT NULL,
	"carbs_g" double precision NOT NULL,
	"fat_g" double precision NOT NULL,
	"fibre_g" double precision,
	"per100g_micros" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"not_reported" jsonb DEFAULT '[]'::jsonb NOT NULL,
	"serving_label" text,
	"serving_g" double precision,
	"serving_ml" double precision,
	"density_g_per_ml" double precision,
	"piece_label" text,
	"piece_g" double precision,
	"label_basis" text NOT NULL,
	"label_values" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"source" text NOT NULL,
	"source_id" text,
	"field_origins" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"confirmed_at" timestamp with time zone NOT NULL,
	"confirmed_by_person_id" integer,
	"label_photo_uid" text,
	"label_photo_sha256" text,
	"ingredients_text" text,
	"is_dairy" boolean DEFAULT false NOT NULL,
	"contains_onion_garlic" boolean DEFAULT false NOT NULL,
	"diet_flags_found" jsonb DEFAULT '[]'::jsonb NOT NULL,
	"diet_checked_at" timestamp with time zone,
	"archived_at" timestamp with time zone,
	CONSTRAINT "household_foods_nutrients_ck" CHECK ("household_foods"."kcal" >= 0 and "household_foods"."protein_g" >= 0 and "household_foods"."carbs_g" >= 0 and "household_foods"."fat_g" >= 0 and ("household_foods"."fibre_g" is null or "household_foods"."fibre_g" >= 0)),
	CONSTRAINT "household_foods_macro_mass_ck" CHECK ("household_foods"."protein_g" + "household_foods"."carbs_g" + "household_foods"."fat_g" <= 105),
	CONSTRAINT "household_foods_amounts_ck" CHECK (("household_foods"."serving_g" is null or "household_foods"."serving_g" > 0) and ("household_foods"."serving_ml" is null or "household_foods"."serving_ml" > 0) and ("household_foods"."density_g_per_ml" is null or "household_foods"."density_g_per_ml" > 0) and ("household_foods"."piece_g" is null or "household_foods"."piece_g" > 0)),
	CONSTRAINT "household_foods_barcode_ck" CHECK ("household_foods"."barcode" is null or "household_foods"."barcode" ~ '^[0-9]{8,14}$'),
	CONSTRAINT "household_foods_state_ck" CHECK ("household_foods"."state" in ('dry', 'cooked', 'raw', 'ready')),
	CONSTRAINT "household_foods_source_ck" CHECK ("household_foods"."source" in ('LABEL', 'OFF', 'MANUAL')),
	CONSTRAINT "household_foods_basis_ck" CHECK ("household_foods"."label_basis" in ('per_serving', 'per_100g', 'per_100ml')),
	CONSTRAINT "household_foods_label_photo_ck" CHECK (("household_foods"."label_photo_uid" is null) = ("household_foods"."label_photo_sha256" is null))
);
